<script setup lang="ts">
import {ref,computed,watch,onUnmounted} from 'vue';import {useRoute,useRouter} from 'vue-router';import {useQuasar} from 'quasar';import {api,errorText} from '../api';import {useAuth} from '../stores/auth';
interface Row {id:string;name?:string;phoneNumber?:string;createdAt:string;status?:string;priority?:string;title?:string;content?:string;direction?:string;channel?:string;source?:string;deliveryStatus?:string;deliveryError?:string;job?:{state:string;errorCode?:string};contact?:Row}
const route=useRoute(),router=useRouter(),auth=useAuth(),q=useQuasar();const drawer=ref(false),busy=ref(false),error=ref(''),items=ref<Row[]>([]),total=ref(0),offset=ref(0),search=ref(''),channel=ref(''),selected=ref<Row|null>(null),messages=ref<Row[]>([]),messageTotal=ref(0),detail=ref(false),create=ref(false),saving=ref(false),contacts=ref<Row[]>([]);const metrics=ref<Record<string,number>|null>(null),settings=ref<any>(null),health=ref('Comprobando');const form=ref({contactId:'',title:'',description:'',priority:'MEDIUM'});
const nav=[{path:'/',label:'Resumen',icon:'space_dashboard'},{path:'/conversations',label:'Conversaciones',icon:'forum'},{path:'/contacts',label:'Contactos',icon:'people_outline'},{path:'/tickets',label:'Tickets',icon:'confirmation_number'},{path:'/settings',label:'Configuración',icon:'tune'}];const title=computed(()=>nav.find(n=>n.path===route.path)?.label||'Resumen');const resource=computed(()=>route.path.slice(1));const dark=ref(localStorage.getItem('sentia-dark')==='true');q.dark.set(dark.value);watch(dark,v=>{q.dark.set(v);localStorage.setItem('sentia-dark',String(v))});
async function load(){busy.value=true;error.value='';items.value=[];try{if(route.path==='/')metrics.value=(await api.get('/api/dashboard')).data;else if(route.path==='/settings'){settings.value=(await api.get('/api/settings')).data;try{health.value=(await api.get('/health')).data.status==='ok'?'Disponible':'Degradada'}catch{health.value='No disponible'}}else{const {data}=await api.get('/api/'+resource.value,{params:{offset:offset.value,search:search.value,channel:channel.value||undefined}});items.value=data.items;total.value=data.total}}catch(e){error.value=errorText(e)}finally{busy.value=false}}
watch(()=>route.path,()=>{offset.value=0;search.value='';selected.value=null;void load()},{immediate:true});
async function open(row:Row){error.value='';try{if(resource.value==='conversations'){selected.value=(await api.get('/api/conversations/'+row.id)).data;messages.value=[];messageTotal.value=0;await moreMessages()}else selected.value=(await api.get('/api/contacts/'+row.id)).data;detail.value=true}catch(e){error.value=errorText(e)}}
async function refreshMessages(){if(!selected.value||resource.value!=='conversations')return;const id=selected.value.id;const limit=Math.max(50,messages.value.length);const collected=new Map<string,Row>();let count=0;for(let skip=0;skip<limit;skip+=50){const {data}=await api.get('/api/conversations/'+id+'/messages',{params:{offset:skip}});count=data.total;for(const m of data.items)collected.set(m.id,m);if(skip+50>=count)break}if(selected.value?.id!==id)return;messages.value=[...collected.values()].sort((a,b)=>new Date(b.createdAt).getTime()-new Date(a.createdAt).getTime()||b.id.localeCompare(a.id));messageTotal.value=count}
let polling=false;const historyTimer=setInterval(async()=>{if(!detail.value||polling)return;polling=true;try{await refreshMessages()}catch{error.value='No se pudo actualizar el historial'}finally{polling=false}},5000);onUnmounted(()=>clearInterval(historyTimer));
const agentErrors:Record<string,string>={AI_AUTH:'La clave de Gemini no permite acceder al modelo.',AI_QUOTA:'Gemini alcanzó su cuota o límite de solicitudes.',AI_UNAVAILABLE:'Gemini no está disponible temporalmente.',AI_TIMEOUT_OR_NETWORK:'Gemini no respondió a tiempo o falló la conexión.',AI_EMPTY:'Gemini no devolvió una respuesta.',AI_BLOCKED:'El proveedor bloqueó la respuesta.',AI_REQUEST:'Gemini rechazó la solicitud; revisa el modelo configurado.',META_AUTH:'Meta rechazó las credenciales.',META_RATE_LIMIT:'Meta alcanzó su límite de solicitudes.',META_TIMEOUT_OR_NETWORK:'No se pudo confirmar el resultado del envío.',SEND_RESULT_UNKNOWN:'El servidor se reinició sin confirmar el envío. Revisa Meta antes de reenviar.',WINDOW_EXPIRED:'Terminó la ventana de atención de WhatsApp; se requiere una plantilla aprobada.',AI_RECOVERY_EXHAUSTED:'No se pudo recuperar la generación tras varios intentos.'};
const agentError=(code:string)=>agentErrors[code]||'No se pudo completar la operación; requiere revisión administrativa.';
const deliveryLabels:Record<string,string>={AVAILABLE:'Disponible en el chat',UNKNOWN:'Sin estado histórico',RECEIVED:'Recibido',PENDING:'Pendiente',SENDING:'Enviando',SENT:'Aceptado por Meta',DELIVERED:'Entregado',READ:'Leído',FAILED:'Fallido',UNCERTAIN:'Envío sin confirmar'};
async function moreMessages(){if(!selected.value)return;const {data}=await api.get('/api/conversations/'+selected.value.id+'/messages',{params:{offset:messages.value.length}});const merged=new Map(messages.value.map(m=>[m.id,m]));for(const m of data.items)merged.set(m.id,m);messages.value=[...merged.values()];messageTotal.value=data.total}
async function openCreate(){try{contacts.value=(await api.get('/api/contacts')).data.items;form.value={contactId:'',title:'',description:'',priority:'MEDIUM'};create.value=true}catch(e){error.value=errorText(e)}}
async function save(){saving.value=true;try{await api.post('/api/tickets',form.value);create.value=false;q.notify({type:'positive',message:'Ticket creado'});await load()}catch(e){q.notify({type:'negative',message:errorText(e)})}finally{saving.value=false}}
async function status(row:Row,value:string){try{await api.patch('/api/tickets/'+row.id,{status:value});await load()}catch(e){error.value=errorText(e)}}
const date=(s:string)=>new Date(s).toLocaleString('es-MX');function logout(){auth.logout();void router.push('/login')}
</script>
<template><q-layout view="lHh Lpr lFf"><q-header class="topbar"><q-toolbar><q-btn flat round icon="menu" class="lt-md" aria-label="Abrir navegación" @click="drawer=!drawer"/><q-breadcrumbs class="muted"><q-breadcrumbs-el label="Espacio de trabajo"/><q-breadcrumbs-el :label="title"/></q-breadcrumbs><q-space/><q-btn flat round :icon="dark?'light_mode':'dark_mode'" aria-label="Cambiar tema" @click="dark=!dark"/><q-separator vertical inset class="q-mx-md"/><q-avatar size="34px" color="primary" text-color="white">{{auth.user?.name.charAt(0)}}</q-avatar><span class="q-ml-sm gt-xs">{{auth.user?.name}}</span></q-toolbar></q-header><q-drawer v-model="drawer" show-if-above :width="242" class="sidebar"><div class="brand"><span class="brand-mark">S</span> SENTIA<small>BRIGADA 105</small></div><div class="nav-caption">ESPACIO DE TRABAJO</div><q-list padding><q-item v-for="n in nav" :key="n.path" clickable :to="n.path" exact active-class="nav-active"><q-item-section avatar><q-icon :name="n.icon"/></q-item-section><q-item-section>{{n.label}}</q-item-section></q-item></q-list><div class="sidebar-bottom"><div class="workspace-card"><q-icon name="shield" color="purple-3" size="24px"/><strong>Brigada 105</strong><span>Centro de atención</span></div><q-btn flat icon="logout" label="Cerrar sesión" @click="logout"/></div></q-drawer><q-page-container><q-page class="page"><div class="eyebrow">CENTRO DE ATENCIÓN · SENTIA</div><div class="page-heading"><div><h1>{{route.path==='/'?'Una vista de lo que importa.':title}}</h1><p class="muted">{{route.path==='/'?'El pulso de tu atención, en un solo lugar.':'Organiza la atención y da seguimiento a cada solicitud.'}}</p></div><q-btn v-if="resource==='tickets'" color="primary" unelevated icon="add" label="Nuevo ticket" @click="openCreate"/><q-btn v-else flat icon="refresh" label="Actualizar" @click="load"/></div><q-banner v-if="error" class="bg-red-1 text-negative q-mb-md" role="alert">{{error}}<template #action><q-btn flat label="Reintentar" @click="load"/></template></q-banner><q-linear-progress v-if="busy" indeterminate color="primary"/>
<template v-if="route.path==='/'"><div class="metric-grid"><q-card flat bordered v-for="(label,key) in {contacts:'Contactos',conversations:'Conversaciones',openTickets:'Tickets abiertos',resolvedTickets:'Tickets resueltos'}" :key="key" class="metric"><q-icon :name="key==='contacts'?'people_outline':key==='conversations'?'forum':'confirmation_number'"/><span>{{label}}</span><strong>{{metrics?metrics[key]:'—'}}</strong><small>Total registrado en el sistema</small></q-card></div><div class="overview-grid"><q-card flat bordered class="welcome-card"><q-badge color="primary" label="TU CENTRO DE OPERACIONES"/><h2>Más cerca de las personas.<br>Más claridad para tu equipo.</h2><p>Consulta el historial de atención y transforma solicitudes en acciones.</p><q-btn unelevated color="primary" label="Ver conversaciones" icon-right="arrow_forward" to="/conversations"/></q-card><q-card flat bordered class="status-card"><q-icon name="hub" size="34px" color="primary"/><h3>Una base para crecer</h3><p class="muted">El chat web permite atender consultas con Gemini sin configurar WhatsApp. Consulta el estado del asistente en Configuración.</p><q-btn flat color="primary" label="Ver configuración" to="/settings"/></q-card></div></template>
<q-card v-else-if="resource==='settings'" flat bordered class="content-card"><h2>Información del sistema</h2><q-list separator><q-item><q-item-section>Sistema</q-item-section><q-item-section side>SENTIA · Brigada 105</q-item-section></q-item><q-item><q-item-section>API y base de datos</q-item-section><q-item-section side>{{health}}</q-item-section></q-item><q-item><q-item-section>Chat web</q-item-section><q-item-section side>{{settings?.webChat?.active?'IA disponible':'IA no disponible'}}</q-item-section></q-item><q-item><q-item-section>Credenciales WhatsApp</q-item-section><q-item-section side>{{settings?.whatsapp.configured?'Configuradas':'Sin configurar'}}</q-item-section></q-item><q-item><q-item-section>Conexión WhatsApp</q-item-section><q-item-section side>No verificada</q-item-section></q-item><q-item><q-item-section>Inteligencia artificial</q-item-section><q-item-section side>{{settings?.agent?.enabled?'Habilitada':'Deshabilitada'}}</q-item-section></q-item><q-item><q-item-section>Gemini</q-item-section><q-item-section side>{{settings?.agent?.configured?'Clave configurada (sin verificar)':'Sin configurar'}} · {{settings?.agent?.model}}</q-item-section></q-item><q-item><q-item-section>Respuesta automática de WhatsApp</q-item-section><q-item-section side>{{settings?.agent?.active?'Activa':'Inactiva: revisar habilitación y credenciales'}}</q-item-section></q-item></q-list><q-toggle v-model="dark" label="Modo oscuro" class="q-mt-lg"/></q-card>
<q-card v-else flat bordered class="content-card"><div class="row items-center q-mb-lg"><h2 class="q-ma-none">{{title}} <q-badge color="grey-3" text-color="grey-9">{{total}}</q-badge></h2><q-space/><q-select v-if="resource==='conversations'" v-model="channel" dense outlined emit-value map-options :options="[{label:'Todos los canales',value:''},{label:'Web Chat',value:'WEB'},{label:'WhatsApp',value:'WHATSAPP'}]" aria-label="Filtrar por canal" class="q-mr-sm" style="min-width:150px" @update:model-value="offset=0;load()"/><q-input v-if="resource==='conversations'" outlined dense v-model="search" placeholder="Buscar nombre o teléfono" @keyup.enter="offset=0;load()"><template #append><q-btn flat round icon="search" aria-label="Buscar" @click="offset=0;load()"/></template></q-input></div><q-markup-table flat wrap-cells v-if="items.length"><thead><tr><th class="text-left">{{resource==='tickets'?'Solicitud':'Contacto'}}</th><th class="text-left">{{resource==='contacts'?'Teléfono':'Estado'}}</th><th class="text-left">{{resource==='tickets'?'Prioridad':'Registro'}}</th><th>Acción</th></tr></thead><tbody><tr v-for="row in items" :key="row.id"><td><strong>{{row.title||row.contact?.name||row.name}}</strong><div v-if="resource==='tickets'&&row.contact" class="q-mt-xs">Solicitante: {{row.contact.name}}</div><div v-if="row.contact" class="muted">{{row.contact.phoneNumber?.startsWith('web:')?'Visitante del chat web':row.contact.phoneNumber}}</div><q-badge v-if="row.channel" outline color="primary">{{row.channel==='WEB'?'Web Chat':'WhatsApp'}}</q-badge></td><td><q-badge v-if="row.status" :color="row.status==='RESOLVED'?'teal':'deep-purple-1'" :text-color="row.status==='RESOLVED'?'white':'deep-purple'">{{row.status}}</q-badge><span v-else>{{row.phoneNumber?.startsWith('web:')?'Contacto web':row.phoneNumber}}</span></td><td>{{row.priority||date(row.createdAt)}}</td><td><q-select v-if="resource==='tickets'" dense outlined :model-value="row.status" :options="['OPEN','IN_PROGRESS','RESOLVED']" @update:model-value="v=>status(row,v)" aria-label="Estado del ticket"/><q-btn v-else flat color="primary" label="Ver detalle" @click="open(row)"/></td></tr></tbody></q-markup-table><div v-else-if="!busy&&!error" class="empty"><q-icon name="inbox" size="52px"/><h3>Todo listo para comenzar</h3><p class="muted">Aún no hay registros en esta sección.</p></div><div class="row justify-end items-center q-gutter-sm q-mt-md"><q-btn flat label="Anterior" :disable="offset===0||busy" @click="offset-=50;load()"/><span class="muted">{{total?offset+1:0}}–{{Math.min(offset+50,total)}} de {{total}}</span><q-btn flat label="Siguiente" :disable="offset+50>=total||busy" @click="offset+=50;load()"/></div></q-card><footer>SENTIA · Brigada 105 <span>Atención con propósito.</span></footer></q-page></q-page-container>
<q-dialog v-model="detail"><q-card class="detail-card"><q-card-section class="row"><h2>{{selected?.contact?.name||selected?.name}}</h2><q-space/><q-btn flat round icon="close" v-close-popup aria-label="Cerrar"/></q-card-section><q-card-section v-if="resource==='contacts'"><p>{{selected?.phoneNumber?.startsWith('web:')?'Visitante del chat web':selected?.phoneNumber}}</p><p>Registro: {{selected&&date(selected.createdAt)}}</p></q-card-section><q-card-section v-else class="message-list"><q-btn v-if="messages.length<messageTotal" flat label="Cargar mensajes anteriores" @click="moreMessages().catch(e=>q.notify({type:'negative',message:errorText(e)}))"/><div v-for="m in [...messages].reverse()" :key="m.id" :class="['message',{'outbound':m.direction==='OUTBOUND'}]"><div>{{m.content}}</div><small>{{date(m.createdAt)}} · {{m.direction==='INBOUND'?'Persona':m.source==='AI'?'SENTIA · IA':'Humano'}} · {{deliveryLabels[m.deliveryStatus||'UNKNOWN']||m.deliveryStatus}}</small><small v-if="m.deliveryError">{{agentError(m.deliveryError)}}</small><small v-if="m.job?.errorCode">{{agentError(m.job.errorCode)}}</small></div><p v-if="!messages.length" class="muted">Sin mensajes registrados.</p></q-card-section></q-card></q-dialog>
<q-dialog v-model="create"><q-card class="detail-card"><q-card-section><h2>Crear ticket</h2><p class="muted">Da seguimiento a una nueva solicitud.</p></q-card-section><q-card-section><q-form @submit="save" class="q-gutter-md"><q-select outlined v-model="form.contactId" :options="contacts.map(c=>({label:c.name+' · '+c.phoneNumber,value:c.id}))" emit-value map-options label="Contacto" :rules="[v=>!!v||'Selecciona un contacto']"/><p v-if="!contacts.length" class="muted">No hay contactos. Se registran al iniciar una conversación web o recibir mensajes de WhatsApp.</p><q-input outlined v-model="form.title" label="Título" maxlength="200" :rules="[v=>!!v.trim()||'Campo obligatorio']"/><q-input outlined v-model="form.description" type="textarea" label="Descripción" maxlength="10000" :rules="[v=>!!v.trim()||'Campo obligatorio']"/><q-select outlined v-model="form.priority" :options="['LOW','MEDIUM','HIGH']" label="Prioridad"/><div class="row justify-end q-gutter-sm"><q-btn flat label="Cancelar" v-close-popup/><q-btn type="submit" color="primary" unelevated label="Crear ticket" :loading="saving"/></div></q-form></q-card-section></q-card></q-dialog></q-layout></template>
